cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/travel_expenses.xlsx');
console.log('Sheet names:', wb.SheetNames);
console.log();
wb.SheetNames.forEach(name => {
  const ws = wb.Sheets[name];
  const range = XLSX.utils.decode_range(ws['!ref']);
  console.log('Sheet:', name, '| Range:', ws['!ref'], '| Rows:', range.e.r+1, '| Cols:', range.e.c+1);
  // Print all data as JSON to see every column
  const json = XLSX.utils.sheet_to_json(ws, {defval: ''});
  json.forEach(row => console.log(JSON.stringify(row)));
  console.log();
});
"

